Task: The dispatch engine is down. Implement shape-specific area behavior and a total-area routine that relies on each shape's own implementation.

Submitted code:
```
class Shape {
  area() {
    return 0;
  }
}

class Circle extends Shape {
  constructor(radius) {
    super();
    this.radius = radius;
  }

  area() {
    return Math.PI * this.radius * this.radius;
  }
}

class Rectangle extends Shape {
  constructor(width, height) {
    super();
    this.width = width;
    this.height = height;
  }

  area() {
    return this.width * this.height;
  }
}

function totalArea(shapes) {
  const allAreas = shapes.map(shape => shape.area());
  let cumulativeArea = 0;
  for (const currentArea of allAreas) {
    cumulativeArea += currentArea;
  }
  return cumulativeArea;
}
```

